+fn drill() -> Tool {
+    let t = catalog().into_iter().find(|(n, _)| *n == "DR-0600").map(|(_, t)| t).expect("catalog DR-0600");
+    assert_eq!(t.kind, ToolKind::Drill);
+    t
+}
