+    let wide: Vec<f64> = undersize_holes(&t, &p).iter().map(|h| h.radius * 2.0).collect();
+    assert_eq!(wide, vec![6.2, 8.0, 12.0], "D6.00, D6.04 and D6.1 are the drill's size; D6.2, D8 and D12 are not");
